import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { orderService } from '../../services/orderService';
import { productService } from '../../services/productService';
import './Dashboard.css';

const Dashboard = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({ total: 0, pending: 0, delivered: 0 });
  const [recentOrders, setRecentOrders] = useState([]);
  const [recommendedProducts, setRecommendedProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        // Fetch orders
        const orders = await orderService.getMyOrders();
        const orderList = orders || [];
        setRecentOrders(orderList.slice(0, 5));
        setStats({
          total: orderList.length,
          pending: orderList.filter(o => 
            o.status === 'pending' || o.status === 'processing' || o.status === 'shipped'
          ).length,
          delivered: orderList.filter(o => o.status === 'delivered').length
        });

        // Fetch recommended products
        try {
          const products = await productService.getProducts({ limit: 6 });
          setRecommendedProducts(products || []);
        } catch (err) {
          // Silently fail for recommendations
          setRecommendedProducts([]);
        }
      } catch (err) {
        console.error('Error fetching dashboard data:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const fmt = (v) => Number(v || 0).toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

  // Check for any pending orders that need attention
  const hasPendingOrders = stats.pending > 0;

  return (
    <div className="dashboard-page container">
      {/* Welcome Header */}
      <div className="dashboard-header">
        <h1>Welcome back, {user?.name?.split(' ')[0] || 'User'}!</h1>
        <p>Manage your orders, profile, and security here.</p>
      </div>

      {/* Notification Banner for pending orders */}
      {hasPendingOrders && (
        <div className="notification-banner">
          <span className="icon">🔔</span>
          <p>You have {stats.pending} order{stats.pending > 1 ? 's' : ''} in progress. Track them for updates.</p>
        </div>
      )}

      {/* Stats Cards */}
      <div className="dashboard-stats">
        <div className="stat-card total">
          <h3>Total Orders</h3>
          <div className="stat-value">{stats.total}</div>
        </div>
        <div className="stat-card in-progress">
          <h3>In Progress</h3>
          <div className="stat-value">{stats.pending}</div>
        </div>
        <div className="stat-card delivered">
          <h3>Delivered</h3>
          <div className="stat-value">{stats.delivered}</div>
        </div>
      </div>

      {/* Main Content Grid */}
      <div className="dashboard-grid">
        {/* Recent Orders Section */}
        <div className="dashboard-section recent-orders">
          <div className="section-header">
            <h2>Recent Orders</h2>
            <Link to="/my-orders" className="link">View All</Link>
          </div>

          {loading ? (
            <div className="loading">Loading orders...</div>
          ) : recentOrders.length > 0 ? (
            <div className="order-list">
              {recentOrders.map(order => (
                <div key={order._id} className="order-item-mini">
                  <div className="order-info">
                    <span className="order-id">#{ (order._id || order.orderId || 'Unknown').toString().slice(-8).toUpperCase() }</span>
                    <span className="order-date">{new Date(order.createdAt).toLocaleDateString()}</span>
                  </div>
                  <div className="order-meta">
                    <span className="order-amount">{fmt(order.totalAmount || order.total)}</span>
                    <span className={`status-badge ${order.status}`}>
                      {order.status}
                    </span>
                  </div>
                  <Link to={`/track/${order._id || order.orderId}`} className="btn-track">Track</Link>
                </div>
              ))}
            </div>
          ) : (
            <div className="empty-orders">
              <p>No orders yet.</p>
              <Link to="/products" className="btn btn-primary">Start Shopping</Link>
            </div>
          )}
        </div>

        {/* Quick Actions Section */}
        <div className="dashboard-section quick-actions">
          <h2>Quick Actions</h2>
          <div className="action-grid">
            <Link to="/account" className="action-card">
              <div className="icon">👤</div>
              <span>Profile Settings</span>
            </Link>
            <Link to="/wishlist" className="action-card">
              <div className="icon">❤️</div>
              <span>My Wishlist</span>
            </Link>
            <Link to="/cart" className="action-card">
              <div className="icon">🛒</div>
              <span>Go to Cart</span>
            </Link>
            <Link to="/products" className="action-card">
              <div className="icon">🛍️</div>
              <span>Browse Products</span>
            </Link>
          </div>
        </div>
      </div>

      {/* Recommended Products Section */}
      {recommendedProducts.length > 0 && (
        <div className="dashboard-section recommended-section">
          <h2>Recommended for You</h2>
          <div className="recommended-grid">
            {recommendedProducts.map(product => (
              <Link 
                to={`/products/${product._id || product.id}`} 
                className="recommended-item" 
                key={product._id || product.id}
              >
                <img 
                  src={product.images?.[0]?.url || product.image || '/placeholder.png'} 
                  alt={product.name} 
                />
                <div className="name">{product.name}</div>
                <div className="price">{fmt(product.price)}</div>
              </Link>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
